import{_ as i,o as a,c as l,a3 as n,j as e,a as r}from"./chunks/framework.z_KJ15Ep.js";const s="/bilder/import-export-statistik/import-unterrichtsdaten-1.png",o="/bilder/import-export-statistik/import-unterrichtsdaten-2-beispiel.png",S=JSON.parse('{"title":"Unterrichtsdaten aus Excel importieren","description":"","frontmatter":{"title":"Unterrichtsdaten aus Excel importieren","source_pageid":878,"source_revision":5401},"headers":[],"relativePath":"schild3/import-export-statistik/unterrichts-daten-als-excel-daten-verwaltung-import.md","filePath":"schild3/import-export-statistik/unterrichts-daten-als-excel-daten-verwaltung-import.md"}'),u={name:"schild3/import-export-statistik/unterrichts-daten-als-excel-daten-verwaltung-import.md"};function d(c,t,h,p,m,g){return a(),l("div",null,[...t[0]||(t[0]=[n('<h1 id="unterrichtsdaten-aus-excel-importieren" tabindex="-1">Unterrichtsdaten aus Excel importieren <a class="header-anchor" href="#unterrichtsdaten-aus-excel-importieren" aria-label="Permalink to &quot;Unterrichtsdaten aus Excel importieren&quot;">​</a></h1><p>Übernehmen Sie Unterrichts- und Leistungsdaten aus einer Excel-Datei. Prüfen Sie Vorschau, Tabellenblatt und die im Artikel beschriebene Feldstruktur vor dem Import.</p><h2 id="import" tabindex="-1">Import <a class="header-anchor" href="#import" aria-label="Permalink to &quot;Import&quot;">​</a></h2><p><a href="/bilder/import-export-statistik/import-unterrichtsdaten-1.png"><img src="'+s+'" alt="Import von Unterrichtsdaten." loading="lazy"></a></p><p><em>Import von Unterrichtsdaten.</em></p><p>Über <em>&quot;Verwaltung ➜ Import ➜ Unterrichts-Daten (als Excel-Daten)&quot;</em> können Sie Unterrichts- bzw. Leistungsdaten über eine Excelliste importieren.</p><p>Diese Datei kann auch mit anderen Tabellenkalkulationsprogrammen wie Open Office Calc erstellt werden.</p><p>Wählen Sie zuerst Ihre Excel-Datei aus. Enthält sie mehrere Tabellenblätter, wählen Sie anschließend das Blatt mit den zu importierenden Daten.</p><p>Sie bekommen eine Vorschau der Excel-Datei angezeigt.</p><p>Kontrollieren Sie die Vorschau und vergleichen Sie den Aufbau mit dem Abschnitt <strong>Erläuterungen zum Format</strong> weiter unten. Klicken Sie anschließend auf <strong>Daten importieren</strong>.</p><p>Der Knopf <strong>Beispieldaten ansehen</strong> zeigt eine Beispieldatei an.</p><h2 id="erlauterungen-zum-format" tabindex="-1">Erläuterungen zum Format <a class="header-anchor" href="#erlauterungen-zum-format" aria-label="Permalink to &quot;Erläuterungen zum Format&quot;">​</a></h2><p>Wenn Sie auf den Button <strong>Informationen anzeigen</strong> klicken, bekommen Sie folgende Erklärung:</p><p>Hier können Sie Unterrichtsdaten, in Form von Excel-Dateien, importieren. In einer Datei können sowohl Angaben zu klassenbezogenem Unterricht als auch zu Kursen stehen. Diese Dateien müssen den folgenden grundsätzlichen Aufbau haben.</p>',14),e("div",{"data-hint-kind":"important",class:"warning custom-block"},[e("p",{class:"custom-block-title"},[e("svg",{class:"hint-icon","data-icon":"important","aria-hidden":"true",focusable:"false",viewBox:"0 0 24 24",fill:"none",stroke:"currentColor","stroke-width":"1.8","stroke-linecap":"round","stroke-linejoin":"round"},[e("circle",{cx:"12",cy:"12",r:"9"}),e("path",{d:"M12 7v6m0 4v.1"})]),r("Wichtig")]),e("p",null,"Die erste Zeile muss die jeweiligen Spaltenüberschriften enthalten und wird beim Import ignoriert.")],-1),n("<ul><li>Spalte 1 <strong>Kursbezeichnung</strong> (optional): Der Eintrag muss in Kombination mit Jahr, Abschnitt und Jahrgang eindeutig sein! Das Feld kann leer sein, falls es sich um einen Unterricht im Klassenverband handelt, dann muss aber Spalte 2 gefüllt sein.</li><li>Spalte 2 <strong>Klasse</strong> (optional): Die Klassenbezeichnung, muss in der Klassen-/Versetzungstabelle vorhanden sein. Folgende Kombinationen mit der Kursbezeichnung sind möglich: <ul><li>Kursbezeichnung nicht leer, Klasse leer: In diesem Fall wird nur ein Kurs in der Kursverwaltung angelegt, es erfolgt keine Zuteilung von Unterricht an die Schüler.</li><li>Kursbezeichnung nicht leer, Klasse nicht leer: In der Kursverwaltung wird ein Kurs angelegt, dieser wird allen Schülern der Klasse (als Kursunterricht) zugeteilt</li><li>Kursbezeichnung leer, Klasse nicht leer: Es wird kein Kurs in der Kursverwaltung angelegt, der Unterricht wird ohne Kurszuweisung allen Schülern der Klasse zugeordnet (Unterricht im Klassenverband).</li></ul></li><li>Spalte 3 <em>Schuljahr</em></li><li>Spalte 4 <em>Halbjahr</em> bzw. <em>Quartal</em></li><li>Spalte 5 <em>Jahrgang</em> (optional): Die Jahrgangsbezeichnung muss der Bezeichnung in SchILD entsprechen. Falls der Eintrag leer ist, liegt ein jahrgangsübergreifender Kurs vor. Bei Klassenunterricht (Spalte 2 nicht leer) wird die Angabe ignoriert (ebenso, wenn Spalte 1 leer ist).</li><li>Spalte 6 <em>Fach</em>: Die Fachbezeichnung, muss in der Fächertabelle vorhanden sein.</li><li>Spalte 7 <em>Kursart</em> (optional): Die allgemeine Kursart muss in der Tabelle der <em>allg. Kursarten</em> in SchILD vorhanden sein.</li><li>Spalte 8 <em>Wochenstunden</em>: Gesamt-Wochenstunden, so wie sie bei den Schüler-Leistungsdaten eingetragen werden.</li><li>Spalte 9 <em>Wochenstunden Kursleiter</em>: Anz. Wochenstunden, die vom Kursleiter gehalten werden, falls leer, wird Gesamt-Wochenstd. (Spalte 8) angenommen Wird ignoriert, wenn Kursbezeichnung (Spalte 1) leer ist. Dann liegt Unterricht im Klassenverband vor, bei dem die &quot;Hauptlehrkraft&quot; die gesamten Wochenstunden bestreitet.</li><li>Spalte 10 <em>Lehrer</em>: Kursleiter bzw. Fachlehrer (als schulinternes Kürzel)</li></ul>",1),e("div",{"data-hint-kind":"info",class:"info custom-block"},[e("p",{class:"custom-block-title"},[e("svg",{class:"hint-icon","data-icon":"info","aria-hidden":"true",focusable:"false",viewBox:"0 0 24 24",fill:"none",stroke:"currentColor","stroke-width":"1.8","stroke-linecap":"round","stroke-linejoin":"round"},[e("circle",{cx:"12",cy:"12",r:"9"}),e("path",{d:"M12 11v6m0-10v.1"})]),r("Hinweis")]),e("p",null,"Bis hier müssen alle Spalten existieren. Die folgenden Spalten können dagegen fehlen. Wenn allerdings Wochenstunden einer Zusatzkraft (Spalte 13 u. 14) übergeben werden sollen, müssen auch die Spalten 11 u. 12 existieren, die dann aber auch leer sein dürfen, die Spaltenüberschriften müssen aber existieren.")],-1),n('<ul><li>Spalte 11 <em>Epochalunterricht</em>: Als &quot;J&quot; oder &quot;N&quot; (wenn leer, wird &quot;N&quot; gesetzt)</li><li>Spalte 12 <em>Schulnummer</em>: Falls ein Kurs im Rahmen einer Kooperation an einer anderen Schule gegeben wird, kann hier die Schulnr dieser Schule übergeben werden. Wird nur bei Kursunterricht (Spalte 1 nicht leer) berücksichtigt.</li><li>Spalte 13 <em>Wochenstunden Zusatzkraft</em>: Die Wochenstunden einer Zusatzkraft, wird bei Klassenunterricht (Spalte 2 nicht leer) importiert.</li><li>Spalte 14 <em>Zusatzkraft (als schulinternes Kürzel)</em></li><li>Spalte 15, 16 usw. <em>Wochenstunden und Kürzel von weiteren Zusatzkräften</em>: Falls die Kursbezeichnung (Spalte 1) nicht leer ist, können hier im Wechsel beliebig viele Wochenstunden und Kürzel von weiteren Zusatzkräften eingegeben werden. Ist die Kursbezeichnung leer, so werden diese Angaben ignoriert.</li></ul><h2 id="beispiele" tabindex="-1">Beispiele <a class="header-anchor" href="#beispiele" aria-label="Permalink to &quot;Beispiele&quot;">​</a></h2><p><a href="/bilder/import-export-statistik/import-unterrichtsdaten-2-beispiel.png"><img src="'+o+`" alt="Beispieldatei mit Unterrichten." loading="lazy"></a></p><p><em>Beispieldatei mit Unterrichten.</em></p><p>Die folgenden fünf Beispiele sind aus der früheren Dokumentation übernommen. <strong>Die Textbeschreibungen nennen 2022/23, die Datenzeilen enthalten dagegen 2006.</strong> Verwenden Sie diese Zeilen nicht unverändert als Importvorlage. Für einen aktuellen Import müssen Jahr, Abschnitt, Fach- und Kursartkürzel zum Zielbestand passen. Die Reihenfolge der Spalten ist maßgeblich.</p><p>Beispiel 1: 2 Std. Sport als Klassenunterricht in Klasse 06A im 2. Hj. 2022/23 bei Lehrer &quot;BO&quot;, kein Epochenunterricht</p><pre><code>| 06A | 2006 | 2 |   | SP | PUT | 2 |   | BO | N
</code></pre><p>Beispiel 2: 2 Std. Sport als Klassenunterricht in Klasse 06B im 2.Hj. 2022/23 bei Lehrer &quot;BO&quot;, Lehrer &quot;ALD&quot; nimmt 1 Std. als &quot;team-teacher&quot; teil.</p><pre><code>| 06B | 2006 | 2 |   | SP | PUT | 2 |   | Bo | N |   | 1 | ALD
</code></pre><p>Beispiel 3: 2-stündiger Sportkurs &quot;Volleyball&quot; in Jahrgang 07 im 2. Hj. 2022/23, 1 Std. bei Lehrer &quot;BO&quot;, 1 Std. bei Lehrer &quot;ALD&quot;, wird nur als Kurs eingerichtet (d.h. keine Zuweisungen bei Schülern)</p><pre><code>Volleyball |   | 2006 | 2 | 07 | SP | AGGT | 2 | 1 | BO | N |   | 1 | ALD
</code></pre><p>Beispiel 4: 4-stündiger Sportkurs &quot;Sport-1-07a&quot; in Jahrgang 07 im 2. Hj. 2022/23, 3 Std. bei Lehrer &quot;BO&quot;, 1 Std. bei Lehrer &quot;ALD&quot;, 1 Std. bei Lehrer &quot;MÜ&quot;, alle Schüler der Klasse 07A nehmen teil (Hinweis: Wenn Teile des Unterrichtes von mehreren Lehrern gleichzeitig betreut werden, kann die Summe der Lehrerstunden größer als die des Kurses sein.)</p><pre><code>Sport-1-07a | 07A | 2006 | 2 | 07 | SP | AGGT | 4 | 3 | BO | N |   | 1 | ALD | 1 | MÜ
</code></pre><p>Beispiel 5: 2-stündiger Sportkurs &quot;Hockey&quot; in Jahrgang 08 im 2. Hj. 2022/23, wird an Partnerschule mit Schulnr. 123456 gegeben</p><pre><code>Hockey |   | 2006 | 2 | 08 | SP | AGGT | 2 |   |   | N | 123456
</code></pre><hr><p><a href="https://schulverwaltungsinfos.nrw.de/svws/wiki/index.php?title=Unterrichts-Daten_(als_Excel-Daten)_(Verwaltung_Import)" target="_blank" rel="noreferrer">Originalartikel im Wiki</a> · Quellrevision 5401.</p>`,17)])])}const k=i(u,[["render",d]]);export{S as __pageData,k as default};
